/*
 * A013919  Numbers n such that sum of first n composites is composite.
 * https://oeis.org/A013919
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = nth integer m such that the sum of the first m composite
 *            numbers is itself composite. The sequence is generated by
 *            scanning composite numbers, maintaining their cumulative sum,
 *            and storing the composite indices whose sums are composite. The
 *            implementation keeps a cache of generated terms s...
 * Range:     u8 n <= 14, u16 n <= 306, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   isPrimeTrial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include <assert.h>
#include "../utils/isPrimeTrial.h"   /* isPrimeTrial(seq_t n) returns bool */

static seq_t *seq = NULL;          /* sequence values a(k) */
static size_t seq_cap = 0;         /* allocated capacity of seq */
static size_t seq_len = 0;         /* number of values stored in seq */

static idx_t cur_num = 4;          /* next integer to test for compositeness */
static idx_t composite_cnt = 0;    /* number of composites processed so far */
static seq_t sum_comp = 0;         /* cumulative sum of composites processed */

/* Ensure that the sequence array can hold at least 'need' elements. */
static void ensure_seq_cap(size_t need)
{
    if (need > seq_cap) {
        size_t new_cap = seq_cap ? seq_cap * 2 : 16;
        if (new_cap < need)
            new_cap = need;
        seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
        assert(tmp != NULL);
        seq = tmp;
        seq_cap = new_cap;
    }
}

/* Return the nth term of sequence A013919. */
seq_t a(idx_t n)
{
    if (n == 0) { /* sequence offset is 1, but safety check */
        return 0;
    }

    /* Generate terms until we have at least n of them. */
    while (seq_len < (size_t)n) {
        /* Find next composite number. */
        while (true) {
            if (!isPrimeTrial((seq_t)cur_num)) {  /* cur_num is composite */
                /* Update cumulative data for this composite. */
                composite_cnt++;
                sum_comp += (seq_t)cur_num;

                /* Check if the cumulative sum is composite. */
                if (!isPrimeTrial(sum_comp)) {  /* sum is composite */
                    ensure_seq_cap(seq_len + 1);
                    seq[seq_len++] = (seq_t)composite_cnt;
                }
                break;  /* done processing this composite */
            }
            cur_num++;  /* try next integer */
        }
        cur_num++;  /* advance to integer after the composite just processed */
    }

    return seq[n - 1];  /* sequence indices start at 1 */
}
